# ---------- fetching & parsing ----------

def read_feeds():
    feeds = []
    for line in (ROOT / "feeds.txt").read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "|" not in line:
            continue
        name, url = [p.strip() for p in line.split("|", 1)]
        feeds.append((name, url))
    return feeds


def fetch(url):
    req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept": "application/rss+xml, application/xml, text/xml, */*"})
    with urllib.request.urlopen(req, timeout=25) as r:
        return r.read()


def strip_ns(tag):
    return tag.rsplit("}", 1)[-1].lower()


def child_text(el, *names):
    for c in el:
        if strip_ns(c.tag) in names and (c.text or "").strip():
            return c.text.strip()
    return ""


def parse_date(s):
    if not s:
        return None
    try:
        d = parsedate_to_datetime(s)
    except (TypeError, ValueError):
        try:
            d = datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
    if d.tzinfo is None:
        d = d.replace(tzinfo=timezone.utc)
    return d.astimezone(timezone.utc)


def clean(text, limit=None):
    text = html.unescape(re.sub(r"<[^>]+>", " ", text or ""))
    text = re.sub(r"\s+", " ", text).strip()
    text = re.sub(r"(The post .*? appeared first on .*?\.?$)", "", text).strip()
    if limit and len(text) > limit:
        text = text[:limit].rsplit(" ", 1)[0].rstrip(",.;:") + "…"
    return text


def parse_feed(source, raw):
    root = ET.fromstring(raw)
    items = []
    for el in root.iter():
        kind = strip_ns(el.tag)
        if kind not in ("item", "entry"):
            continue
        title = clean(child_text(el, "title"))
        link = child_text(el, "link")
        if not link:  # Atom
            for c in el:
                if strip_ns(c.tag) == "link" and c.get("href") and c.get("rel", "alternate") == "alternate":
                    link = c.get("href")
                    break
        date = parse_date(child_text(el, "pubdate", "published", "updated", "date"))
        summary = clean(child_text(el, "description", "summary", "encoded"), 240)
        src = source
        if "news.google.com" in (link or ""):
            publisher = child_text(el, "source")
            if publisher:
                src = publisher
                title = re.sub(r"\s+-\s+" + re.escape(publisher) + r"$", "", title)
            summary = ""  # Google's summaries just repeat the headline
        if not title or not link or not link.startswith("http"):
            continue
        if re.search(r"\b(sponsored|paid content|advertorial|partner content)\b", title + " " + summary, re.I):
            continue  # other outlets' paid ads
        items.append({
            "title": title,
            "link": link,
            "source": src,
            "summary": summary,
            "published": (date or datetime.now(timezone.utc)).isoformat(),
        })
    return items



def categorize(item):
    text = (item["title"] + " " + item.get("summary", "")).lower()
    for name, pattern in CATEGORIES:
        if re.search(pattern, text):
            return name
    return "Industry"


def key_for(item):
    return re.sub(r"[^a-z0-9]", "", item["title"].lower())[:80]


# ---------- archive ----------

def load_archive():
    if ARCHIVE.exists():
        try:
            return json.loads(ARCHIVE.read_text())
        except json.JSONDecodeError:
            pass
    return []


RELEVANT = re.compile(r"\b(truck\w*|freight\w*|carrier\w*|drivers?|diesel|fuel|fleets?|logistics|cargo|shipping|shippers?|ports?|rail\w*|fmcsa|dot|cdl\w*|highways?|interstate|tariffs?|supply chain|warehouse\w*|brokers?|parking|eld\w*|tolls?|roads?|oil|crude|autonomous|driverless)\b", re.I)


def relevant(i):
    """Keep 'Industry' headlines only if they actually touch trucking or freight."""
    return i["category"] != "Industry" or bool(RELEVANT.search(i["title"] + " " + i.get("summary", "")))


def summary_key(i):
    s = re.sub(r"[^a-z0-9]", "", (i.get("summary") or "").lower())
    return s[:120] if len(s) > 60 else None


def merge(old, new, allowed_sources):
    by_key, seen_links, seen_summaries = {}, set(), set()
    for i in new + old:  # newest copies first
        if i.get("original") or i.get("source") not in allowed_sources:
            continue  # drops sources you've switched off in feeds.txt
        if re.search(r"\b(sponsored|paid content|advertorial|partner content)\b", (i.get("title") or "") + " " + (i.get("summary") or ""), re.I):
            continue  # other outlets' paid ads already in the archive
        k, sk = key_for(i), summary_key(i)
        if k in by_key or i["link"] in seen_links or (sk and sk in seen_summaries):
            continue  # same story re-titled or re-posted
        by_key[k] = i
        seen_links.add(i["link"])
        if sk:
            seen_summaries.add(sk)
    cutoff = datetime.now(timezone.utc) - timedelta(days=KEEP_DAYS)
    now = datetime.now(timezone.utc) + timedelta(hours=1)
    items = [i for i in by_key.values() if cutoff <= datetime.fromisoformat(i["published"]) <= now]
    for i in items:
        i["category"] = categorize(i)
    items = [i for i in items if relevant(i)]
    items.sort(key=lambda i: i["published"], reverse=True)
    return items


# ---------- markdown ----------

def esc(s):
    return html.escape(s or "", quote=True)


def slugify(s):
    return re.sub(r"[^a-z0-9]+", "-", s.lower()).strip("-")[:80]


def inline_md(t):
    t = esc(t)
    t = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", t)
    t = re.sub(r"(?<![\w*])\*(?!\s)(.+?)(?<!\s)\*(?![\w*])", r"<em>\1</em>", t)
    def link(m):
        url = m.group(2)
        ext = not url.startswith("/") and not url.startswith("mailto:")
        return f'<a href="{url}"' + (' target="_blank" rel="noopener"' if ext else "") + f">{m.group(1)}</a>"
    t = re.sub(r"\[([^\]]+)\]\((https?://[^)\s]+|/[^)\s]*|mailto:[^)\s]+)\)", link, t)
    return t


def markdown(md):
    out, para, lst = [], [], None
    def flush():
        nonlocal para, lst
        if para:
            out.append("<p>" + inline_md(" ".join(para)) + "</p>"); para = []
        if lst:
            out.append("<ul>" + "".join(f"<li>{inline_md(x)}</li>" for x in lst) + "</ul>"); lst = None
    for line in md.splitlines():
        s = line.strip()
        if not s:
            flush(); continue
        if s.startswith("### "):
            flush(); out.append(f"<h3>{inline_md(s[4:])}</h3>")
        elif s.startswith("## "):
            flush(); out.append(f"<h2>{inline_md(s[3:])}</h2>")
        elif s[:2] in ("- ", "* "):
            if para: flush()
            lst = (lst or []) + [s[2:]]
        else:
            if lst: flush()
            para.append(s)
    flush()
    return "\n".join(out)


def split_front_matter(text):
    meta, body = {}, text
    if text.startswith("---"):
        _, head, body = text.split("---", 2)
        for line in head.strip().splitlines():
            if ":" in line:
                k, v = line.split(":", 1)
                v = v.strip()
                if len(v) >= 2 and v[0] == v[-1] and v[0] in "\"'":
                    v = v[1:-1]
                meta[k.strip().lower()] = v
    return meta, body


# ---------- our own articles (posts/*.md) ----------

def load_posts():
    posts = []
    if not POSTS.exists():
        return posts
    for f in sorted(POSTS.glob("*.md")):
        meta, body = split_front_matter(f.read_text(encoding="utf-8"))
        if meta.get("draft", "").lower() == "true" or not meta.get("title"):
            continue
        date = parse_date(meta.get("date", "")) or datetime.fromtimestamp(f.stat().st_mtime, timezone.utc)
        slug = meta.get("slug") or slugify(re.sub(r"^\d{4}-\d{2}-\d{2}-", "", f.stem)) or slugify(meta["title"])
        words = len(re.findall(r"\w+", body))
        posts.append({
            "title": meta["title"], "link": f"/news/{slug}/", "slug": slug,
            "source": SITE_NAME, "author": meta.get("author", "OTR News Staff"),
            "summary": meta.get("summary", ""), "category": meta.get("category") or None,
            "published": date.isoformat(), "original": True,
            "minutes": max(1, round(words / 230)), "body": markdown(body),
            "image": meta.get("image", ""), "image_alt": meta.get("image_alt", ""),
            "credit": meta.get("credit", ""), "credit_url": meta.get("credit_url", ""), "section": meta.get("section", "").lower(), "partner": meta.get("partner", ""),
        })
    posts.sort(key=lambda p: p["published"], reverse=True)
    return posts


