def load_pages():
    pages = default_pages()
    if PAGES.exists():
        for f in PAGES.glob("*.md"):
            meta, body = split_front_matter(f.read_text(encoding="utf-8"))
            name = f.stem.lower()
            old = pages.get(name, (name.title(), "", ""))
            pages[name] = (meta.get("title", old[0]), meta.get("summary", old[1]), body)
    return pages




