VIDEO_STOP = set("this that with from your what when have will they their about into than then them more most over under after before driver drivers truck trucks trucking cdl news guide how".split())


def related_video(p):
    """A matching trucking video under an article (or the newest one if nothing matches)."""
    try:
        vids = json.loads(VIDEOS_FILE.read_text()).get("videos") or []
    except Exception:
        return ""
    if not vids:
        return ""
    words = lambda t: {w for w in re.findall(r"[a-z0-9]+", (t or "").lower()) if len(w) > 3 and w not in VIDEO_STOP}
    want = words(p["title"] + " " + p.get("summary", ""))
    best, score = vids[0], 0
    for v in vids[:60]:
        sc = len(want & words(v["title"]))
        if sc > score:
            best, score = v, sc
    label = "Related video" if score else "Latest trucking video"
    return (f'<section class="tool-card"><h2>{label}</h2><div class="vgrid" style="grid-template-columns:1fr">{video_card(best)}</div>'
            f'<a class="more-link" href="/videos/">More trucking videos</a></section>' + VIDEO_CSS + VIDEO_JS)


def share_html(url, title, label="Share this story"):
    """Share buttons. On phones, 'Share' opens the phone's own share menu (Facebook app, Messages, WhatsApp, etc.)."""
    q = urllib.parse.quote
    u, t = q(url, safe=""), q(title, safe="")
    return f"""<div class="share"><span>{esc(label)}</span>
<button type="button" class="share-native" data-url="{esc(url)}" data-title="{esc(title)}" hidden>Share</button>
<a href="https://www.facebook.com/sharer/sharer.php?u={u}" target="_blank" rel="noopener">Facebook</a>
<a href="https://twitter.com/intent/tweet?url={u}&text={t}" target="_blank" rel="noopener">X</a>
<a href="sms:?&body={t}%20{u}">Text</a>
<a href="mailto:?subject={t}&body={u}">Email</a>
<button type="button" class="share-copy" data-url="{esc(url)}">Copy link</button>
</div>
<script>(function(){{var s=document.currentScript.previousElementSibling,n=s.querySelector('.share-native'),c=s.querySelector('.share-copy');
if(navigator.share){{n.hidden=false;n.addEventListener('click',function(){{navigator.share({{title:n.dataset.title,url:n.dataset.url}}).catch(function(){{}});}});}}
c.addEventListener('click',function(){{if(navigator.clipboard)navigator.clipboard.writeText(c.dataset.url).then(function(){{c.textContent='Link copied';}});}});}})();</script>"""


def render_article(p, posts, tpl, pages):
    d = datetime.fromisoformat(p["published"])
    url = SITE_URL + p["link"]
    q = urllib.parse.quote
    share = share_html(url, p["title"])
    hero = ""
    if p.get("image"):
        if p.get("credit") and p.get("credit_url"):
            credit = f'<figcaption><a href="{esc(p["credit_url"])}" target="_blank" rel="noopener">{esc(p["credit"])}</a></figcaption>'
        else:
            credit = f'<figcaption>{esc(p["credit"])}</figcaption>' if p.get("credit") else ""
        hero = (f'<figure class="hero"><img src="{esc(p["image"])}" alt="{esc(p.get("image_alt") or p["title"])}" '
                f'loading="eager">{credit}</figure>')
    others = [o for o in posts if o is not p][:4]
    more = ""
    if others:
        more = '<section class="more"><h2>More from OTR News</h2>' + "".join(story_html(o) for o in others) + "</section>"
    body = f"""<article>
<p class="meta"><a class="cat" href="/topics/{topic_slug(p['category'])}/">{esc(p['category'])}</a></p>
<h1>{esc(p['title'])}</h1>
<p class="deck">{esc(p['summary'])}</p>
{hero}
<p class="byline"><span>By {esc(p['author'])}</span><time datetime="{p['published']}">{d.strftime('%B %-d, %Y')}</time><span>{p['minutes']} min read</span></p>
<div class="body">
{p['body']}
</div>
{share}
</article>
{training_box()}
{partner_box(partner_named(p['partner'])) if p.get('partner') and partner_named(p['partner']) else ("".join(partner_box(x) for x in section_partners(p.get('section', ''))) or partner_box(pick_partner(p['category'], p['slug'])))}
{related_video(p)}
{lodoshop_ad()}
{newsletter_box()}
{more}
<a class="back" href="/">All trucking news</a>"""
    ld = {"@context": "https://schema.org", "@type": "NewsArticle", "headline": p["title"],
          "datePublished": p["published"], "dateModified": p["published"],
          "author": {"@type": "Organization", "name": p["author"]},
          "publisher": {"@type": "Organization", "name": SITE_NAME,
                        "logo": {"@type": "ImageObject", "url": f"{SITE_URL}/icon.png"}},
          "image": [SITE_URL + p["image"] if p.get("image", "").startswith("/") else f"{SITE_URL}/cards/card-{topic_slug(p['category'])}.png"],
          "articleSection": p["category"], "description": p["summary"], "mainEntityOfPage": url}
    og = p["image"] if p.get("image", "").startswith("/") else f"/cards/card-{topic_slug(p['category'])}.png"
    return shell(tpl, pages, og_image=og, title=p["title"], description=p["summary"], path=p["link"],
                 body=body, og_type="article", ld=ld)


def render_page(name, page, tpl, pages):
    title, desc, md = page
    body = f'<h1>{esc(title)}</h1>\n<div class="body">\n{markdown(md)}\n</div>\n<a class="back" href="/">All trucking news</a>'
    return shell(tpl, pages, title=title, description=desc or title, path=f"/{name}/", body=body)


