def fmt_date(iso):
    return datetime.fromisoformat(iso).strftime("%b %-d, %Y")


def thumb_src(i, lead=False):
    if i.get("image"):
        return i["image"]
    return f"/cards/{'card' if lead else 'thumb'}-{topic_slug(i['category'])}.png"


def story_html(i, lead=False):
    orig = i.get("original")
    cls = ("story lead" if lead else "story") + (" original" if orig else "") + (" has-thumb" if orig else "")
    summary = f'<p class="dek">{esc(i["summary"])}</p>' if i.get("summary") else ""
    tag = "h2" if lead else "h3"
    target = "" if orig else ' target="_blank" rel="noopener"'
    img = ""
    if orig:
        alt = esc(i.get("image_alt") or "")
        img = (f'<a class="thumb" href="{esc(i["link"])}" tabindex="-1" aria-hidden="true">'
               f'<img src="{esc(thumb_src(i, lead))}" alt="{alt}" loading="{"eager" if lead else "lazy"}"></a>')
    return f"""<article class="{cls}" data-cat="{esc(i["category"])}">
  {img}<div class="story-text">
  <p class="meta"><a class="cat" href="/topics/{topic_slug(i["category"])}/">{esc(i["category"])}</a><span class="src">{esc(i["source"])}</span><time datetime="{esc(i["published"])}">{fmt_date(i["published"])}</time></p>
  <{tag}><a href="{esc(i["link"])}"{target}>{esc(i["title"])}</a></{tag}>
  {summary}
  </div>
</article>"""


def question_of_the_day():
    """One practice-test question on the homepage, changing daily."""
    if not QUIZ:
        return ""
    day = datetime.now(timezone.utc).timetuple().tm_yday + datetime.now(timezone.utc).year * 366
    cat, q, answers, why = QUIZ[day % len(QUIZ)]
    order = sorted(range(len(answers)), key=lambda n: (n * 7 + day) % len(answers))
    btns = "".join(f'<button type="button" class="qd-a" data-ok="{1 if n == 0 else 0}">{esc(answers[n])}</button>' for n in order)
    return f"""<section class="qotd" aria-label="Question of the day">
<p class="kicker">CDL question of the day &middot; {esc(cat)}</p>
<h2>{esc(q)}</h2>
<div class="qd-answers">{btns}</div>
<p class="qd-why" hidden><strong class="qd-verdict"></strong> {esc(why)}</p>
<a class="more-link" href="/tools/cdl-practice-test/">Take the full practice test</a>
<script>
(function(){{
  var box = document.currentScript.parentNode;
  box.querySelectorAll('.qd-a').forEach(function(b){{
    b.addEventListener('click', function(){{
      box.querySelectorAll('.qd-a').forEach(function(x){{ x.disabled = true; if (x.dataset.ok === '1') x.classList.add('right'); }});
      if (b.dataset.ok !== '1') b.classList.add('wrong');
      var w = box.querySelector('.qd-why'); w.hidden = false;
      box.querySelector('.qd-verdict').textContent = b.dataset.ok === '1' ? 'Correct.' : 'Not quite.';
    }});
  }});
}})();
</script>
</section>"""


