SW_JS = """const V='otr-v1';const CORE=['/','/offline.html','/icon.png','/app-192.png'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(V).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==V).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{const r=e.request;if(r.method!=='GET')return;const u=new URL(r.url);if(u.origin!==location.origin)return;
if(r.mode==='navigate'){e.respondWith(fetch(r).then(res=>{const c=res.clone();caches.open(V).then(x=>x.put(r,c));return res;}).catch(()=>caches.match(r).then(m=>m||caches.match('/offline.html'))));return;}
if(['/images/','/cards/','/partners/'].some(p=>u.pathname.startsWith(p))||['.png','.jpg','.jpeg','.webp'].some(x=>u.pathname.endsWith(x))){e.respondWith(caches.match(r).then(m=>m||fetch(r).then(res=>{const c=res.clone();caches.open(V).then(x=>x.put(r,c));return res;})));}});
"""


def write_app_files(tpl, pages):
    for name, data in APP_ICONS.items():
        (SITE / name).write_bytes(base64.b64decode(data))
    manifest = {"name": SITE_NAME, "short_name": SITE_NAME, "description": TAGLINE, "start_url": "/?source=app",
                "scope": "/", "display": "standalone", "background_color": "#ffffff", "theme_color": "#00603C",
                "icons": [{"src": "/app-192.png", "sizes": "192x192", "type": "image/png"},
                          {"src": "/app-512.png", "sizes": "512x512", "type": "image/png"},
                          {"src": "/app-maskable-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable"}],
                "shortcuts": [{"name": "Job board", "url": "/jobs/"}, {"name": "CDL practice test", "url": "/tools/cdl-practice-test/"},
                              {"name": "Guides", "url": "/guides/"}]}
    (SITE / "manifest.webmanifest").write_text(json.dumps(manifest, indent=1))
    (SITE / "sw.js").write_text(SW_JS)
    (SITE / "offline.html").write_text(shell(tpl, pages, title="You're offline", description="No connection.", path="/offline.html",
        body='<h1>No signal right now</h1><div class="body"><p>Stories you opened recently are still available. The latest news will load when you are back in range.</p></div><a class="back" href="/">Try again</a>'))
    out = SITE / "app"
    out.mkdir(parents=True, exist_ok=True)
    (out / "index.html").write_text(shell(tpl, pages, title="Get the OTR News app",
        description="Install OTR News on your phone: trucking news, CDL jobs, and free driver tools on your home screen.",
        path="/app/", body=APP_PAGE + newsletter_box()))


